CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE permisos (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), codigo varchar(80) NOT NULL UNIQUE, descripcion varchar(255));
CREATE TABLE roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), codigo varchar(40) NOT NULL UNIQUE, nombre varchar(80) NOT NULL);
CREATE TABLE usuarios (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), nombre varchar(100) NOT NULL, apellido varchar(100) NOT NULL DEFAULT '', email varchar(254) NOT NULL, password_hash varchar(255), credential_status varchar(20) NOT NULL DEFAULT 'PENDIENTE', activo boolean NOT NULL DEFAULT true, is_owner boolean NOT NULL DEFAULT false, protected_account boolean NOT NULL DEFAULT false, deleted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT ck_owner_protected CHECK (NOT is_owner OR protected_account));
CREATE UNIQUE INDEX ux_usuarios_email_normalizado ON usuarios (lower(email)) WHERE deleted_at IS NULL;
CREATE TABLE usuarios_roles (usuario_id uuid REFERENCES usuarios(id) ON DELETE CASCADE, rol_id uuid REFERENCES roles(id) ON DELETE CASCADE, PRIMARY KEY(usuario_id,rol_id));
CREATE TABLE roles_permisos (rol_id uuid REFERENCES roles(id) ON DELETE CASCADE, permiso_id uuid REFERENCES permisos(id) ON DELETE CASCADE, PRIMARY KEY(rol_id,permiso_id));
CREATE TABLE usuarios_permisos (usuario_id uuid REFERENCES usuarios(id) ON DELETE CASCADE, permiso_id uuid REFERENCES permisos(id) ON DELETE CASCADE, PRIMARY KEY(usuario_id,permiso_id));
CREATE TABLE password_reset_tokens (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), usuario_id uuid NOT NULL REFERENCES usuarios(id), token_hash varchar(64) NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, used_at timestamptz, revoked_at timestamptz);
CREATE INDEX ix_password_reset_usuario ON password_reset_tokens(usuario_id);
CREATE TABLE user_sessions (id uuid PRIMARY KEY, usuario_id uuid NOT NULL REFERENCES usuarios(id), refresh_token_hash varchar(64) NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, last_used_at timestamptz NOT NULL DEFAULT now(), revoked_at timestamptz, device_name varchar(120), device_platform varchar(40));
CREATE INDEX ix_sessions_usuario ON user_sessions(usuario_id);
CREATE TABLE proyectos (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), nombre varchar(160) NOT NULL, direccion varchar(255) NOT NULL, comuna varchar(120), descripcion text, activo boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE cabeceras (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), proyecto_id uuid NOT NULL REFERENCES proyectos(id), nombre varchar(120) NOT NULL, capacidad integer NOT NULL CHECK (capacidad IN (94,144)), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(proyecto_id,nombre));
CREATE TABLE puertos (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), cabecera_id uuid NOT NULL REFERENCES cabeceras(id) ON DELETE CASCADE, numero integer NOT NULL CHECK(numero>0), estado varchar(20) NOT NULL DEFAULT 'LIBRE' CHECK(estado IN ('LIBRE','RESERVADO','OCUPADO')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(cabecera_id,numero));
CREATE TABLE sectores (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), cabecera_id uuid NOT NULL REFERENCES cabeceras(id), piso varchar(30) NOT NULL, lado varchar(10) NOT NULL, activo boolean NOT NULL DEFAULT true, orden_visual integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(cabecera_id,piso,lado));
CREATE TABLE departamentos (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sector_id uuid NOT NULL REFERENCES sectores(id), numero varchar(30) NOT NULL, activo boolean NOT NULL DEFAULT true, orden_visual integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(sector_id,numero));
CREATE TABLE operadores (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), nombre varchar(120) NOT NULL, codigo varchar(40) NOT NULL UNIQUE, activo boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE posiciones_departamento (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), departamento_id uuid NOT NULL REFERENCES departamentos(id), tipo varchar(3) NOT NULL CHECK(tipo IN ('OP1','OP2')), puerto_id uuid UNIQUE REFERENCES puertos(id), operador_id uuid REFERENCES operadores(id), estado varchar(20) NOT NULL DEFAULT 'LIBRE' CHECK(estado IN ('LIBRE','RESERVADA','ASIGNADA')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(departamento_id,tipo));
CREATE TABLE cables (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), proyecto_id uuid NOT NULL REFERENCES proyectos(id), nombre varchar(120) NOT NULL, codigo varchar(50) NOT NULL UNIQUE, cantidad_fibras integer NOT NULL CHECK(cantidad_fibras>0), activo boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE tubos (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), cable_id uuid NOT NULL REFERENCES cables(id) ON DELETE CASCADE, numero integer NOT NULL, color varchar(30) NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(cable_id,numero));
CREATE TABLE fibras (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tubo_id uuid NOT NULL REFERENCES tubos(id) ON DELETE CASCADE, numero_global integer NOT NULL, numero_en_tubo integer NOT NULL, color varchar(30) NOT NULL, estado varchar(20) NOT NULL DEFAULT 'LIBRE' CHECK(estado IN ('LIBRE','ASIGNADA','FUSIONADA')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tubo_id,numero_en_tubo));
CREATE TABLE conexiones_fibra (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), posicion_id uuid NOT NULL REFERENCES posiciones_departamento(id), fibra_id uuid NOT NULL REFERENCES fibras(id), activo boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX ux_conexion_posicion_activa ON conexiones_fibra(posicion_id) WHERE activo;
CREATE UNIQUE INDEX ux_conexion_fibra_activa ON conexiones_fibra(fibra_id) WHERE activo;
CREATE TABLE fusiones (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), conexion_id uuid NOT NULL REFERENCES conexiones_fibra(id), fibra_id uuid NOT NULL REFERENCES fibras(id), fusionador_id uuid NOT NULL REFERENCES usuarios(id), fecha timestamptz NOT NULL, estado varchar(30) NOT NULL, observaciones text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE SEQUENCE certificacion_numero_seq START 1;
CREATE TABLE certificaciones (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), numero_certificacion varchar(20) NOT NULL UNIQUE DEFAULT ('CERT-' || lpad(nextval('certificacion_numero_seq')::text,6,'0')), proyecto_id uuid NOT NULL REFERENCES proyectos(id), cabecera_id uuid NOT NULL REFERENCES cabeceras(id), sector_id uuid NOT NULL REFERENCES sectores(id), certificador_id uuid NOT NULL REFERENCES usuarios(id), estado varchar(20) NOT NULL DEFAULT 'BORRADOR' CHECK(estado IN ('BORRADOR','FINALIZADA','APROBADA','RECHAZADA','ANULADA')), fecha_certificacion date NOT NULL DEFAULT current_date, observaciones text, aprobado_por uuid REFERENCES usuarios(id), fecha_aprobacion timestamptz, rechazado_por uuid REFERENCES usuarios(id), fecha_rechazo timestamptz, anulado_por uuid REFERENCES usuarios(id), fecha_anulacion timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE mediciones (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), certificacion_id uuid NOT NULL REFERENCES certificaciones(id), conexion_id uuid REFERENCES conexiones_fibra(id), departamento_id uuid NOT NULL REFERENCES departamentos(id), operador_posicion varchar(3) NOT NULL CHECK(operador_posicion IN ('OP1','OP2')), longitud_onda varchar(10) NOT NULL CHECK(longitud_onda IN ('1310','1490','1550','LOG')), valor numeric(10,3), unidad varchar(20) NOT NULL DEFAULT 'dBm', log boolean NOT NULL DEFAULT false, observacion text, tecnico_id uuid NOT NULL REFERENCES usuarios(id), fecha_medicion timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(certificacion_id,departamento_id,operador_posicion,longitud_onda));
CREATE TABLE configuracion_empresa (id integer PRIMARY KEY DEFAULT 1 CHECK(id=1), nombre varchar(160), rut varchar(30), direccion varchar(255), telefono varchar(50), correo varchar(254), logo bytea, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE auditoria (id bigserial PRIMARY KEY, usuario_id uuid REFERENCES usuarios(id), accion varchar(80) NOT NULL, entidad varchar(80), entidad_id varchar(80), descripcion text, valor_anterior jsonb, valor_nuevo jsonb, resultado varchar(30) NOT NULL DEFAULT 'OK', fecha timestamptz NOT NULL DEFAULT now(), ip varchar(64));
CREATE INDEX ix_auditoria_fecha ON auditoria(fecha DESC);

